package org.example;

import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        System.out.println("Hello world!");
//        System.out.println(Main.findTheDifference("abcd"   , "abcde"));
//        System.out.println(Main.findTheDifference("abde"   , "abcde"));
//        System.out.println(Main.findTheDifference("aa"   , "aaa"));
//        System.out.println(Main.findTheDifference(""   , "x"));
        System.out.println(Main.findTheDifference(""   , ""));

    }

    public static char findTheDifference(String s, String t) {
        if(s.isEmpty()) return t.toCharArray()[0];
        char[] chars = s.toCharArray();
        char [] chart = t.toCharArray();
        Arrays.sort(chars);
        Arrays.sort(chart);
        int i = 0;
        int j = 0;
        while (i < s.length() && j < t.length()){
            if(chars[i] != chart[j]) return chart[j];
            i++;
            j++;
        }
        return chart[chart.length - 1];
    }
}